sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.script:
(function() {
	var language = gs.getSession().getLanguage();//gs.getMessage($sp.getParameter("language"));
	var caseNumber = gs.getMessage($sp.getParameter("requestNumber"));
	var anonymous = gs.getMessage($sp.getParameter("anonymous")); //Used in Anonymous Harassement & Violence cases
	var flu = gs.getMessage($sp.getParameter("flu")); //Used in Flu cases
	var hr_service = gs.getMessage($sp.getParameter("hrService")); //Used in hv cases
	var message = "";
	if (language == "en"){
		if (hr_service == "hv") {
			message+= "<br>Good day,<br><br> Your request has been successfully submitted. <br><br>";
		} else {
			message+= "<br>Good day,<br><br> Your request has been successfully submitted. The case number is {caseNumber}. <br><br>";
		}

		if (anonymous != "True" && anonymous != "Vrai" && anonymous != "true" && anonymous != "vrai"){
			message+= "A confirmation email has been sent to you with the necessary details. <br><br>";

			if (hr_service == "hv") {
				message+= "You may be contacted shortly to provide the necessary follow-up. <br><br>";
			} else {
				message+= "You will be contacted shortly to provide the necessary follow-up. <br><br>";
			}
		} 

		if (flu == "True" || flu == "Vrai" || flu == "true" || flu == "vrai"){
			message+= "A confirmation email has been sent to you with the necessary details. <br><br>";
		}

		if (hr_service=="hv") {
			message+= "For immediate assistance, you may contact <a href='mailto:RW.rmt@parl.gc.ca'>Respectful Workplace</a>. <br><br>";
			message+= "Thank you<br><br>";
		} else {
			message+= "For immediate assistance, you may contact <a href='mailto:OHS-SST@parl.gc.ca'>Occupational Health & Safety</a>. <br><br>";
			message+= "Thank you, <br><br>";
			message+= "OHS Management System <br>";
		}

	}
	if (language == "fq"){
		if (hr_service == "hv") {
			message+= "<br>Bonne journée,<br><br> Votre demande a été soumise avec succès. <br><br>";
		} else {
			message+= "<br>Bonne journée,<br><br> Votre demande a été soumise avec succès. Le numéro de dossier est {caseNumber}. <br><br>";
		}

		if (anonymous != "True" && anonymous != "Vrai" && anonymous != "true" && anonymous != "vrai"){
			message+= "Un courriel de confirmation vous a été envoyé contenant les informations nécessaires.  <br><br>";

			if (hr_service == "hv") {
				message+= "Vous pouvez être contacté sous peu afin d'assurer un suivit. <br><br>";
			} else {
				message+= "Vous serez contacté sous peu afin d'assurer un suivit. <br><br>";
			}
		} 		

		if (flu == "True" || flu == "Vrai" || flu == "true" || flu == "vrai"){
			message+= "Un courriel de confirmation vous a été envoyé contenant les informations nécessaires.  <br><br>";
		}
		//Respect en Milieu de Travail
		if (hr_service=="hv") {
			message+= "Pour une assistance immédiate, vous pouvez contacter <a href='mailto:RW.rmt@parl.gc.ca'>Respect en Milieu de Travail</a>. <br><br>";
			message+= "Merci<br><br>";
		} else {
			message+= "Pour une assistance immédiate, vous pouvez contacter <a href='mailto:OHS-SST@parl.gc.ca'>Santé et sécurité au travail</a>. <br><br>";
			message+= "Merci, <br><br>";
			message+= "Système de gestion de la SST <br>";
		}

	}

	message = message.replace("{caseNumber}", caseNumber)
	data.message = message;

})();
